tokio::task::spawn_blocking(move || -> Result<String, String> {
        let argv = build_clone_argv(
            &token,
            &repo_full_name,
            Path::new(&target),
            branch.as_deref(),
        );
        let output = git_command()?
            .args(&argv)
            .output()
            .map_err(|err| format!("Failed to spawn bundled git clone: {err}"))?;
